'use strict';

/**
* Return the global object.
*
* @module @stdlib/utils/global-object
*
* @example
* var getGlobal = require( '@stdlib/utils/global-object' );
*
* var g = getGlobal();
* // returns <global_object>
*/

// MODULES //

var getGlobal = require( './main.js' );


// EXPORTS //

module.exports = getGlobal;
EOF

